/*
 * Iranian Mosque-Inspired Rippling Pattern
 * Drop this into ShaderToy or similar.
 */

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // 1. Normalize pixel coords so that (0,0) is screen center,
    //    and the smaller dimension is 1.0 unit.
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    // 2. Time variable
    float t = iTime;

    // 3. Convert to polar coordinates
    float r = length(uv);
    float a = atan(uv.y, uv.x);

    // 4. Define how many times we want to repeat around the circle (symmetry)
    //    For Nasir al-Mulk–style patterns, 8, 12, 16, etc. can look interesting.
    float k = 1.0;

    // 5. "Fold" the angle so the pattern repeats k times around the center
    //    We do this by restricting a to one slice, then reflecting it back out
    //    to the original [0, 2π) range.
    a = fract(a / (2.0 * 3.14159 / k)) * (2.0 * 3.14159 / k);

    // 6. Add a small radial ripple distortion (like folding/rippling).
    //    The ripple’s "phase" can use time, so it moves or pulses.
    float rippleFreq = 53.0;   // how many ripple waves outward
    float rippleAmp  = 0.2;   // amplitude of the ripple
    float ripple = sin(r * rippleFreq - t * 2.0) * rippleAmp;
    r += ripple;

    // 7. Convert back to Cartesian
    vec2 pos = vec2( r * cos(a), r * sin(a) );

    // 8. Start building a color. We can sample a fractal-like function or
    //    combine trig waveforms. Let’s do some wave layering for color.
    float wave = sin(pos.x * 5.0 + pos.y * 5.0 + t * 2.0)
               + 0.5 * sin(pos.x * 10.0 - pos.y * 10.0 - t * 3.0);

    // Remap wave from [-1,1] to [0,1]
    float w = 0.5 + 0.5 * wave;

    // 9. Construct a color from w, layering phases.
    //    We'll shift phases for each channel a bit
    vec3 color = vec3(
        sin(w * 6.28 + 0.0),
        sin(w * 6.28 + 2.0),
        sin(w * 6.28 + 4.0)
    );
    color = 0.5 + 0.5 * color; // keep color within [0..1]

    // 10. Gradually fade color towards black as we move away from the center
    color *= 1.0 - 0.8 * r;  // adjust fade strength to taste

    // 11. Output final color
    fragColor = vec4(color, 1.0);
}
